package com.bank.audit;

import java.util.*;
import java.util.logging.*;
import static java.util.stream.Collectors.*;

public class TopDeptTopEarnersDemo {
    private static final Logger log = Logger.getLogger("Audit");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee("Rajesh", "IT", 1000000),
            new Employee("Amit", "IT", 900000),
            new Employee("Karan", "IT", 800000),
            new Employee("Vikram", "IT", 700000),   // IT total huge
            new Employee("Priya", "Sales", 500000));
        AuditService service = new AuditService();

        log.info(() -> "Top 3 earners of top-spend dept: "
            + service.topEarnersOfTopSpendDept(staff, 3));
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final String name;
    private final String department;
    private final double salary;
    Employee(String name, String department, double salary) {
        this.name = name; this.department = department; this.salary = salary;
    }
    String getName() { return name; }
    String getDepartment() { return department; }
    double getSalary() { return salary; }
}

// ─── Would be in service/AuditService.java ───
class AuditService {
    List<String> topEarnersOfTopSpendDept(List<Employee> staff, int topN) {
        // stage 1: department with highest total salary
        Optional<String> topDept = staff.stream()
            .collect(groupingBy(Employee::getDepartment, summingDouble(Employee::getSalary)))
            .entrySet().stream()
            .max(Map.Entry.comparingByValue())
            .map(Map.Entry::getKey);
        // stage 2: top N earners within that department
        return topDept.map(dept -> staff.stream()
                .filter(e -> e.getDepartment().equals(dept))
                .sorted(Comparator.comparingDouble(Employee::getSalary).reversed())
                .limit(topN)
                .map(Employee::getName)
                .toList())
            .orElse(List.of());
    }
}
